class Particle {
	constructor(){
  	this.posX = random(width); 
		this.posY = random(height);
		this.incr = 0; 
		this.theta = 0;
		let adj = map(this.posY, 0, height, 205, 0);
		this.c = color(10, int(adj), 255);
	}


  update() {
    this.incr += 0.000128;
    this.theta = noise(this.posX * 0.008, this.posY * 0.008, this.incr) * TWO_PI;
    let spiral = sin(this.incr * 2) * 20; 
    this.posX += 2 * cos(this.theta) + spiral * sin(this.theta);
    this.posY += 2 * sin(this.theta) + spiral * cos(this.theta);
  }

  display() {
		let n = noise(0.01*width)
    if (this.posX > 0 && this.posX < width && this.posY > 0  && this.posY < height) {
      // pixels[int(this.posX) + int(this.posY) * width] =  this.c;
			set(int(this.posX) ,int(this.posY), this.c)
			set(int(this.posX +n) ,int(this.posY +random(5)), color(255,255,255,random(1)))

    }
  }

  wrap() {
    if (this.posX < 0){this.posX = width;}
    if (this.posX > width ){ this.posX =  0;}
    if (this.posY < 0 ){ this.posY = height;}
    if (this.posY > height) {this.posY =  0;}
  }

	get move(){
		this.update();
		this.wrap();
		this.display();
	}

}
